// Original, self-contained specimens. All interactions are scoped and released.
const base=`.sample{box-sizing:border-box;min-height:210px;width:100%;height:100%;display:grid;place-items:center;align-content:center;gap:18px;padding:24px;background:#efeee9;color:#202020;font-family:Arial,Meiryo,sans-serif;overflow:hidden}.sample *{box-sizing:border-box}.sample button{min-height:40px;border:1px solid #777;border-radius:999px;background:transparent;padding:9px 17px;font:12px Arial,Meiryo,sans-serif;color:inherit;cursor:pointer}.sample label{font-size:11px;display:grid;gap:8px;width:min(100%,220px)}.sample input{width:100%;accent-color:#222}.sample small{font-size:10px;line-height:1.6}.sample :focus-visible{outline:2px solid #222;outline-offset:4px}@media(prefers-reduced-motion:reduce){.sample *{animation:none!important;transition:none!important}}`;
function controls(root){const abort=new AbortController();for(const input of root.querySelectorAll('[data-target]')){const update=()=>{const target=root.querySelector(input.dataset.target);if(input.dataset.attr)target.setAttribute(input.dataset.attr,input.value+(input.dataset.unit||''));else target.style.setProperty(input.dataset.prop,input.value+(input.dataset.unit||''));const output=input.closest('label')?.querySelector('output');if(output)output.textContent=input.value};input.addEventListener('input',update,{signal:abort.signal});update()}for(const button of root.querySelectorAll('[data-toggle]'))button.addEventListener('click',()=>{const target=root.querySelector(button.dataset.toggle),on=target.classList.toggle('changed');button.setAttribute('aria-pressed',String(on));},{signal:abort.signal});return {destroy(){abort.abort()},setAuto(){}}}
export const explorations=[];
function add({id,category,name,ja,description,use,tip,tags,html,css,source}){const full=base+css;explorations.push({id,category,name,ja,description,use,tip,tags,html,css:full,source,type:'interactive',mount:controls,code:`<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;min-height:300px}${full}</style><div class="sample">${html}</div><script>const controller=(${controls.toString()})(document);addEventListener('pagehide',()=>controller.destroy(),{once:true});</script></html>`})}
add({id:'motion-css-path',category:'motion',name:'CSS motion path',ja:'道筋に沿って動かす',description:'移動する道筋と、その上の進行位置を分けて指定します。曲がる方向に要素の向きも追従できます。',use:'案内図、軌跡、ローディングなど、直線だけでは伝わらない動き。',tip:'進行位置のスライダーを往復させてください。offset-pathで道筋、offset-distanceで位置を指定しています。',tags:['曲線','軌跡','path','移動','CSS'],html:'<div class="path-scene"><svg viewBox="0 0 220 120" aria-hidden="true"><path d="M20 90 C40 5 150 5 200 90"/></svg><b class="path-dot">→</b></div><label>道の上の位置 <output>35</output>%<input type="range" aria-label="道の上の位置" min="0" max="100" value="35" data-target=".path-dot" data-prop="offset-distance" data-unit="%"></label>',css:'.path-scene{width:220px;height:120px;position:relative}.path-scene svg{position:absolute;inset:0;width:220px;height:120px;fill:none;stroke:#999;stroke-width:1;stroke-dasharray:3 5}.path-dot{position:absolute;left:0;top:0;display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:#222;color:#fff;offset-path:path("M20 90 C40 5 150 5 200 90");offset-distance:35%;offset-rotate:auto}',source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/offset-path'});
add({id:'svg-displacement',category:'svg',name:'Displacement filter',ja:'ノイズで輪郭をゆがめる',description:'ノイズの濃淡を位置のずれに変換して、文字や図形に波打つような輪郭をつくります。',use:'水面や熱、揺らぐ素材を感じさせるビジュアル。',tip:'ゆがみを0にすると元の文字に戻ります。feTurbulenceのノイズをfeDisplacementMapに渡します。強すぎる変形は読みにくさにつながります。',tags:['SVG','フィルター','ノイズ','ゆがみ','質感'],html:'<svg viewBox="0 0 280 130" role="img" aria-label="ゆがみが変わるgoodの文字"><defs><filter id="warp" x="-30%" y="-50%" width="160%" height="200%"><feTurbulence baseFrequency=".018 .04" numOctaves="2" seed="4" result="noise"/><feDisplacementMap in="SourceGraphic" in2="noise" scale="16" xChannelSelector="R" yChannelSelector="G"/></filter></defs><text x="140" y="88" text-anchor="middle" font-size="82" font-weight="bold" letter-spacing="-6" filter="url(#warp)">good</text></svg><label>ゆがみの強さ <output>16</output><input type="range" aria-label="ゆがみの強さ" min="0" max="45" value="16" data-target="feDisplacementMap" data-attr="scale"></label>',css:'.sample svg{width:min(100%,280px);height:130px}',source:'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/feDisplacementMap'});
add({id:'type-text-path',category:'type',name:'Text on a path',ja:'曲線に文字を沿わせる',description:'文字の並ぶ基準線を曲線にして、文字組みをひとつの形として見せます。',use:'円形の見出し、ラベル、タイポグラフィのアクセント。',tip:'開始位置を変えると、曲線の同じ場所を文字がたどります。文字は画像にせず、SVGのtextPathとして残しています。',tags:['文字','曲線','SVG','textPath'],html:'<svg viewBox="0 0 280 155" role="img" aria-label="曲線に沿うgooooooooood expression"><defs><path id="type-road" d="M12 112 Q140 -50 268 112"/></defs><path d="M12 112 Q140 -50 268 112" fill="none" stroke="#bbb"/><text font-size="24" font-weight="bold"><textPath href="#type-road" startOffset="5%">gooooooooood expression</textPath></text></svg><label>文字の開始位置 <output>5</output>%<input type="range" aria-label="文字の開始位置" min="0" max="35" value="5" data-target="textPath" data-attr="startOffset" data-unit="%"></label>',css:'.sample svg{width:min(100%,280px);height:155px}',source:'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/textPath'});
add({id:'type-line-reveal',category:'type',name:'Masked line reveal',ja:'行の内側から文字が現れる',description:'行ごとに表示範囲を区切り、その外から文字を動かすことで、文字がせり上がって見えます。',use:'見出しの登場、章の切り替え、短いメッセージ。',tip:'表示を切り替え、上端・下端で文字が切れるところを観察してください。overflowで隠し、transformと時間差で動かします。',tags:['文字','登場','マスク','時間差'],html:'<div class="line-stack" aria-label="FLYING BRAIN"><div><b>FLYING</b></div><div><b>BRAIN</b></div></div><button data-toggle=".line-stack" aria-pressed="false">表示を切り替える</button>',css:'.line-stack{width:100%;font-size:clamp(28px,6vw,46px);font-weight:800;letter-spacing:-2px;line-height:1.1}.line-stack>div{overflow:hidden;padding:2px}.line-stack b{display:block;transition:transform .75s cubic-bezier(.2,.8,.2,1)}.line-stack>div+div b{transition-delay:.12s}.line-stack.changed b{transform:translateY(115%)}',source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/overflow'});
add({id:'ui-skeleton',category:'ui',name:'Skeleton loading',ja:'内容が入る前の形を見せる',description:'読み込み中に、画像や文章が入る場所の輪郭を見せます。光が通り過ぎるシマーを加えると、待機状態がわかります。',use:'実際にデータ取得が必要なカードや一覧。',tip:'切り替えはデモ用です。実装では取得状態と結びつけ、永遠に読み込み中にしないこと。動きを減らす環境では光を動かしません。',tags:['ローディング','読み込み','待機','シマー','UI'],html:'<div class="skeleton-card"><div class="skeleton-image"></div><div class="skeleton-copy"><b>Something good.</b><span>見つける、その少し前。</span></div></div><button data-toggle=".skeleton-card" aria-pressed="false">読み込み状態を切り替える</button>',css:'.skeleton-card{width:min(100%,250px);height:130px;background:white;padding:16px;border:1px solid #ddd;display:flex;gap:16px;align-items:center}.skeleton-image{width:64px;height:80px;background:#222;flex-shrink:0}.skeleton-copy{min-width:0;display:grid;gap:12px}.skeleton-copy b{font-size:15px}.skeleton-copy span{font-size:10px}.skeleton-card.changed .skeleton-image,.skeleton-card.changed .skeleton-copy>*{color:transparent;background:linear-gradient(110deg,#ddd 20%,#f5f5f5 45%,#ddd 70%);background-size:250% 100%;animation:skeleton-shine 1.6s linear infinite}.skeleton-card.changed .skeleton-copy>*{border-radius:3px}@keyframes skeleton-shine{to{background-position:-250% 0}}',source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Animations/Using'});
add({id:'layout-container-query',category:'layout',name:'Container queries',ja:'部品の幅に合わせて組み替える',description:'画面全体ではなく、部品を包む領域の幅を基準にレイアウトを切り替えます。',use:'サイドバーにも本文にも配置するカード、再利用するUI部品。',tip:'幅を変え、160pxを境に縦並びと横並びが変わるところを見てください。未対応ブラウザでは基本の縦並びで表示します。',tags:['レスポンシブ','部品','余白','レイアウト','container'],html:'<div class="container-frame"><div class="query-container"><div class="query-card"><b>g*e</b><span>SPACE<br>CHANGES<br>EXPRESSION.</span></div></div></div><label>部品の幅 <output>100</output>%<input type="range" aria-label="部品の幅" min="45" max="100" value="100" data-target=".query-container" data-prop="width" data-unit="%"></label>',css:'.container-frame{width:250px;max-width:100%;height:150px;display:grid;place-items:center}.query-container{container-type:inline-size;container-name:expression;outline:1px dashed #999;padding:8px;min-width:0}.query-card{display:flex;flex-direction:column;gap:12px;background:white;padding:12px}.query-card b{font-size:28px;letter-spacing:-2px}.query-card span{font-size:9px;line-height:1.4;letter-spacing:1px}@container expression (min-width:160px){.query-card{flex-direction:row;align-items:center;justify-content:space-between}}',source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Containment/Container_queries'});
add({id:'shape-composite-mask',category:'shape',name:'Mask composition',ja:'マスクを引き算して輪郭を残す',description:'二つのマスクの重なる部分を除き、内側が透けた輪郭をつくります。背景に画像があっても中を塗りつぶす必要がありません。',use:'グラデーションの枠、透明なフレーム、複雑な切り抜き。',tip:'マスクの厚みを変えてみてください。mask-composite: excludeでマスクを組み合わせます。',tags:['マスク','輪郭','合成','枠','透明'],html:'<div class="mask-scene"><div class="mask-ring"></div><b>g*e</b></div><label>輪郭の厚み <output>14</output>px<input type="range" aria-label="輪郭の厚み" min="2" max="35" value="14" data-target=".mask-ring" data-prop="padding" data-unit="px"></label>',css:'.mask-scene{width:180px;height:140px;position:relative;display:grid;place-items:center;background:repeating-linear-gradient(45deg,transparent 0 9px,#ddd 9px 10px)}.mask-scene b{font-size:36px;z-index:1}.mask-ring{position:absolute;inset:0;border-radius:40px;padding:14px;background:linear-gradient(130deg,#111,#aaa);mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0);mask-composite:exclude}',source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/mask-composite'});
add({id:'motion-seamless-loop',category:'motion',name:'Seamless marquee',ja:'切れ目なく流れる繰り返し',description:'同じ長さの内容を二組並べ、一組ぶんだけ動かして繰り返すと、継ぎ目を感じない流れになります。',use:'短いキーワードの帯、装飾的なタイポグラフィ。重要な文章の読む手段にはしないこと。',tip:'動きを止めるボタンを用意します。二組の幅と余白が揃わないと継ぎ目で跳ねます。複製した文字は読み上げ対象から外します。',tags:['ループ','文字','marquee','連続','横移動'],html:'<div class="marquee"><div class="marquee-track"><span>gooooooooood* &nbsp; </span><span aria-hidden="true">gooooooooood* &nbsp; </span></div></div><button data-toggle=".marquee" aria-pressed="false">停止／再開</button>',css:'.marquee{width:100%;overflow:hidden;border-block:1px solid #bbb;padding-block:28px}.marquee-track{width:max-content;display:flex;animation:marquee-travel 10s linear infinite}.marquee-track span{display:block;white-space:pre;font-size:38px;font-weight:800;letter-spacing:-2px}.marquee.changed .marquee-track{animation-play-state:paused}@keyframes marquee-travel{to{transform:translateX(-50%)}}',source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/animation-play-state'});
